const reviews = $input.all().map((i) => i.json).filter((r) => Number(r.rating || 5) <= 2);
const byApp = {};
const clip = (str, maxWords = 11) => String(str || "").replace(/\s+/g, " ").trim().split(" ").slice(0, maxWords).join(" ");
for (const r of reviews) {
  const app = r.appName || "Unknown App";
  if (!byApp[app]) byApp[app] = { appName: app, totalLowStar: 0, crashCount: 0, billingCount: 0, crashQuotes: [], billingQuotes: [] };
  const g = byApp[app];
  g.totalLowStar += 1;
  const tags = Array.isArray(r.painSignals) ? r.painSignals : [];
  const body = String(r.text || r.title || "");
  const isCrash = tags.includes("crash_bug") || /crash|freeze|bug|hang|won.?t open/i.test(body);
  const isBilling = tags.includes("billing_subscription") || /bill|charge|cancel|refund|subscription|paywall/i.test(body);
  if (isCrash) {
    g.crashCount += 1;
    if (g.crashQuotes.length < 2 && body) g.crashQuotes.push(clip(body));
  }
  if (isBilling) {
    g.billingCount += 1;
    if (g.billingQuotes.length < 2 && body) g.billingQuotes.push(clip(body));
  }
}
return Object.values(byApp).map((g) => {
  const q1 = g.crashQuotes[0] ? `"${g.crashQuotes[0]}..."` : "recent stability drops";
  const q2 = g.billingQuotes[0] ? `"${g.billingQuotes[0]}..."` : "unexpected billing friction";
  let draftBody = `Pulled ${g.totalLowStar} recent 1-2 star ${g.appName} reviews (${g.crashCount} crash, ${g.billingCount} billing). Users mention ${q1} and ${q2}. Happy to share the full CSV breakdown and bug-cluster summary if your team tracks churn signals — want me to send it over?`;
  const words = draftBody.trim().split(/\s+/);
  if (words.length >= 80) draftBody = words.slice(0, 76).join(" ") + "?";
  return {
    json: {
      appName: g.appName,
      totalLowStar: g.totalLowStar,
      crashCount: g.crashCount,
      billingCount: g.billingCount,
      subject: `${g.totalLowStar} recent 1-2★ ${g.appName} crash & billing signals`,
      dataBaitBody: draftBody,
      wordCount: draftBody.trim().split(/\s+/).length,
    },
  };
});
